from pathlib import Path
import json, csv, statistics, hashlib, subprocess
root=Path(__file__).resolve().parents[3]
report=root/'reports/algorithm-results/exp02-paired-profiles-20261027-r1'
raw=report/'raw'
summary=[]
for profile,label in [('ts02_constant_integrator','T-S02 constant integrator'),('ts03_singular_integrator','T-S03 singular integrator')]:
 rows=[json.loads(x) for x in (raw/f'{profile}.jsonl').read_text().splitlines()]
 measured=[r for r in rows if r['event']=='trial' and not r.get('warmup') and r.get('strategy')]
 for strategy in ['csl.synthesis.reach-back','csl.synthesis.strategy-b']:
  vals=[r['timings_ns']['end_to_end_strategy']['value'] for r in measured if r['strategy']==strategy]
  summary.append({'profile':profile,'case':label,'strategy':strategy,'n':len(vals),'median_ns':int(statistics.median(vals)),'min_ns':min(vals),'max_ns':max(vals),'all_passed':all(r['status']=='passed' and r['termination']=='completed' and r['outcome']=='optimal' and r['complete_family_verified'] and r['distinct_witnesses']==2 for r in measured if r['strategy']==strategy)})
# Summary files
with (report/'summary.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=summary[0].keys()); w.writeheader(); w.writerows(summary)
(report/'summary.json').write_text(json.dumps({'schema':'csl.exp02-paired-profile-summary/1','result_classification':'descriptive; performance-inconclusive','profiles':summary,'limitations':['load average was collected after rather than before the timed runs','perf and a profiler-instrumented build were unavailable; source-mapped limiter is unknown','only T-S02 and T-S03 exact profiles are covered; no scalability or general winner claim']},indent=2)+'\n')
# Standalone SVG analytic feasible optimal control set illustrations
for profile,title,desc,edge in [
 ('ts02_constant_integrator','T-S02 · constant objective','Every control pair in [0,1]² is feasible and optimal.','all'),
 ('ts03_singular_integrator','T-S03 · singular integrator','Feasible controls fill [0,1]²; the optimum is the edge u₁ = 1.','top')]:
 fill='<rect x="100" y="90" width="400" height="300" fill="#d8e9f5" stroke="#17324d" stroke-width="3"/>'
 if edge=='all': mark='<rect x="100" y="90" width="400" height="300" fill="none" stroke="#d76b00" stroke-width="8" stroke-dasharray="12 8"/>'
 else: mark='<line x1="100" y1="90" x2="500" y2="90" stroke="#d76b00" stroke-width="9"/>'
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="720" height="500" viewBox="0 0 720 500"><rect width="100%" height="100%" fill="white"/><text x="60" y="45" font-family="sans-serif" font-size="24" font-weight="bold">{title}</text><text x="60" y="75" font-family="sans-serif" font-size="15">{desc}</text>{fill}{mark}<line x1="100" y1="390" x2="500" y2="390" stroke="#222"/><line x1="100" y1="390" x2="100" y2="90" stroke="#222"/><text x="280" y="430" font-family="sans-serif" font-size="18">u₀</text><text x="55" y="245" font-family="sans-serif" font-size="18" transform="rotate(-90 55 245)">u₁</text><text x="92" y="414" font-family="sans-serif" font-size="14">0</text><text x="494" y="414" font-family="sans-serif" font-size="14">1</text><text x="78" y="395" font-family="sans-serif" font-size="14">0</text><text x="78" y="96" font-family="sans-serif" font-size="14">1</text><rect x="520" y="140" width="18" height="18" fill="#d8e9f5" stroke="#17324d"/><text x="550" y="155" font-family="sans-serif" font-size="15">feasible controls</text><line x1="520" y1="190" x2="540" y2="190" stroke="#d76b00" stroke-width="7"/><text x="550" y="195" font-family="sans-serif" font-size="15">optimal controls</text><text x="60" y="475" font-family="sans-serif" font-size="12" fill="#444">Analytic projection from the saved scenario; illustrates the entire optimal control family, not only sampled witnesses.</text></svg>'''
 out=report/f'{profile}-control-projection.svg'; out.write_text(svg)
 subprocess.run(['rsvg-convert','-o',str(out.with_suffix('.png')),str(out)],check=True)
# README
lines=['# EXP-02 paired exact-profile slice','', 'This is a partial, descriptive comparison for the exact T-S02 constant-integrator and T-S03 singular-integrator profiles. The run uses one process and one shared setup per profile, one excluded warmup pair, then five measured A/B, B/A alternating pairs. Each timed strategy interval includes family construction, selection, and original-problem verification of two distinct witnesses. Process startup and shared setup are outside those intervals.','', '## Result','', '| Profile | Strategy | n | Median (ns) | Range (ns) | Check |','|---|---|---:|---:|---:|---|']
for r in summary: lines.append(f"| {r['case']} | {r['strategy']} | {r['n']} | {r['median_ns']:,} | {r['min_ns']:,}–{r['max_ns']:,} | {'pass' if r['all_passed'] else 'FAIL'} |")
lines += ['', 'The timing medians are descriptive. No winner or bottleneck claim is made: load was not captured before measurement, and this host lacks `perf` and a profiler-instrumented executable. The limiter remains unknown. This is not a scalability result or completion of EXP-02.', '', '## Geometry', '', 'The SVG/PNG panels show analytical projections of each complete optimal control family in the `(u₀,u₁)` plane: T-S02 has a constant objective over the square; T-S03 minimizes `(u₁−1)²`, so its optimal set is the upper edge. The figures are derived from the scenario definitions and are separate from sampled witness verification.', '', '## Reproduction and evidence', '', 'Run `python3 run.py --executable /absolute/path/to/registered_synthesis_comparison`, then `python3 render_report.py` to regenerate the summary and analytical figures from retained JSONL. The runner refuses to overwrite raw evidence and enforces 300 seconds CPU, 300 seconds wall, and 8 GiB address-space limits over each entire profile process. The outer limits are stricter than the per-attempt contract in scope and should not be read as an observed memory measurement. `raw/` retains JSONL, stdout, stderr, process metadata, scenario hashes, and executable hashes. Process wall times were 0.052113 s (T-S02) and 0.063438 s (T-S03).', '', 'The source revision is `2977b95bab581a343c2daba02459f96014e893b0`. The executable was built in Release mode with GCC 16.2.1 (`-O3 -DNDEBUG`), CMake 3.31.6, HiGHS 1.11.0 and Qhull 8.0.2. Its SHA-256 is `300863246730c863d12ddd95090a5d0e0350a3389fb39019dc4e29e6e9274384`. The host was Linux x86_64 with 8 logical CPUs. Load average was checked after the runs (0.18, 1.37, 1.27), not before or during them.', '', 'The event rows report numerical assurance. Each completed row reports complete-family verification, two distinct witnesses, and original feasibility/objective verification; optimality assurance remains numerical and no formal proof is claimed.', '', 'Issue #94 remains open; this slice does not cover T-S01, the full module substitution matrix, resolved hull/V-H workloads, or source profiling.']
(report/'README.md').write_text('\n'.join(lines)+'\n')
